style.css:
@-moz-document domain("roblox.com") {
html {
        background: #000 !important;
    }

    body {
        background: transparent !important;
    }

    body::before {
        content: "";
        position: fixed !important;
        left: 0 !important;
        top: 0 !important;
        width: 100vw !important;
        height: 100vh !important;

        background: url("https://media1.tenor.com/m/XOSOCjqXcNIAAAAC/surfing-nyan-cat.gif") center center / cover no-repeat !important;

        position: fixed !important;
        z-index: 0 !important;
        pointer-events: none !important;
    }

    body > * {
        position: relative;
        z-index: 1;
    }

    #container-main,
    .content,
    .rbx-body,
    .rbx-body-generic,
    .rbx-left-col,
    .rbx-right-col {
        background: transparent !important;
    }
}
